fn split_and_append(list: &Vec<i32>, n: usize) -> Vec<i32> {
    // Since 0 < n < list.len(), we can safely split at n.
    // Create the new vector by extending it with the slice from n..end,
    // then extend with the slice from 0..n.
    let mut new_list = Vec::with_capacity(list.len());
    new_list.extend_from_slice(&list[n..]);
    new_list.extend_from_slice(&list[..n]);
    new_list
}